384	# ---- reviewer timing charts (best-effort ASCII Gantt) ----
385	gantt_file="$WORK_DIR/gantt.md"
386	: >"$gantt_file"
387	if [ "$GANTT_ENABLED" -eq 1 ] && [ -n "$TIMING_LEDGER" ] && [ -f "$TIMING_LEDGER" ] && [ -s "$round_windows_file" ]; then
388	    gantt_awk="$WORK_DIR/gantt.awk"
389	    cat >"$gantt_awk" <<'AWK'
390	function isint(v) { return v ~ /^[0-9]+$/ }
391	function base(path,    n, parts) {
392	    n = split(path, parts, "/")
393	    return parts[n]
394	}
395	function is_ci_task_kind(kind,    k) {
396	    k = tolower(kind)
397	    return (k == "codex-ci" || k == "cursor-ci" || k == "claude-ci" ||
398	        k == "codex-ci-fix" || k == "cursor-ci-fix" || k == "claude-ci-fix" ||
399	        k ~ /-ci$/ || k ~ /-ci-fix$/ || k ~ /-ci-test$/)
400	}
401	function is_ci_output_basename(out,    bn) {
402	    bn = tolower(base(out))
403	    return (bn == "ci.out" || bn ~ /-ci\.out$/ || bn ~ /^ci-fix-.*\.out$/)
404	}
405	function is_launcher_probe_basename(out,    bn) {
406	    bn = tolower(base(out))
407	    return (bn == "claude.out" || bn == "codex.out" || bn == "cursor.out")
408	}
409	function skip_gantt_row(kind, out) {
410	    return (is_ci_task_kind(kind) || is_ci_output_basename(out) ||
411	        is_launcher_probe_basename(out))
412	}
413	function label_for(out, vendor, kind,    bn, val) {
414	    bn = base(out)
415	    if (bn in m) return m[bn]
416	    if (bn != "" && bn != "-") {
417	        val = derive(bn)
418	        if (val ~ /^(cursor|codex|claude_sub|claude)$/ && kind != "" && kind != "-") return val "/" kind
